CREATE TABLE IF NOT EXISTS memory_records(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,user_id UUID NOT NULL,scope TEXT NOT NULL CHECK(scope IN ('TENANT','USER','SESSION')),content TEXT NOT NULL CHECK(length(content)<=20000),embedding JSONB NULL,importance REAL NOT NULL DEFAULT 0.5 CHECK(importance>=0 AND importance<=1),provenance TEXT NOT NULL CHECK(length(provenance)>0),epistemic_state TEXT NOT NULL DEFAULT 'UNVERIFIED',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),expires_at TIMESTAMPTZ NULL);
CREATE INDEX IF NOT EXISTS idx_memory_tenant_user_created ON memory_records(tenant_id,user_id,created_at DESC);
